def slug(s): return ''.join(c for c in s if c.isalnum()).lower()[:20] or 'dev'
def pick(dev):
    n=(dev.name or '').strip().lower()
    if 'هیدروکن' in (dev.name or '') or 'مخروطی' in (dev.name or '') or 'hydrocone' in n or 'gyratory' in n: return cone
    if 'فکی' in (dev.name or '') or 'jaw' in n: return jaw
    if 'فیدر' in (dev.name or '') or 'feeder' in n: return feeder
    tpl=(dev.template.name if dev.template_id else '').strip()
    if tpl=='سنگ‌شکن': return cone
    return MAP.get(tpl, lambda a,b: f'<rect width="240" height="170" rx="18" fill="{a}"/>')
count=0
for dev in Device.objects.select_related('template').all():
    c1,c2=PALETTE.get({'crusher':'crusher','mill':'mill','screen':'screen','magnet':'magnet','conveyor':'conveyor','filter':'filter','tank':'tank','flotation':'flotation','cyclone':'cyclone','dryer':'dryer','flask':'flask','feeder':'feeder'}.get({v:k for k,v in {'سنگ‌شکن':'crusher','آسیای گلوله‌ای':'mill','سرند ارتعاشی':'screen','سپراتور مغناطیسی':'magnet','نوار نقاله':'conveyor','فیلتر پرس':'filter','تیکنر':'tank','سلول فلوتاسیون':'flotation','هیدروسیکلون':'cyclone','خشک‌کن':'dryer','آنالایزر پرتونگاری':'flask'}.items()}.get(dev.template.name,''),'gear'), PALETTE['gear'])
    # direct palette by template
    tpl=(dev.template.name if dev.template_id else '')
    pal={'سنگ‌شکن':('crusher'),'آسیای گلوله‌ای':('mill'),'سرند ارتعاشی':('screen'),'سپراتور مغناطیسی':('magnet'),'نوار نقاله':('conveyor'),'فیلتر پرس':('filter'),'تیکنر':('tank'),'سلول فلوتاسیون':('flotation'),'هیدروسیکلون':('cyclone'),'خشک‌کن':('dryer'),'آنالایزر پرتونگاری':('flask')}
    key=pal.get(tpl,'gear')
    # feeder overrides
    if 'فیدر' in (dev.name or '') or 'feeder' in (dev.name or '').lower(): key='feeder'
    if 'هیدروکن' in (dev.name or '') or 'مخروطی' in (dev.name or ''): key='crusher'
    if 'فکی' in (dev.name or ''): key='crusher'
    c1,c2=PALETTE[key]
    fn=pick(dev)
    svg=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 240 170">{fn(c1,c2)}</svg>'
    fname='dev_%d_%s_v4.svg' % (dev.id, slug(dev.name))
    fpath=os.path.join(BASE, fname)
    open(fpath,'w',encoding='utf-8').write(svg)
    for old in os.listdir(BASE):
        if old.startswith('dev_%d_' % dev.id) and old!=fname:
            try: os.remove(os.path.join(BASE, old))
            except: pass
    dev.image='devices/'+fname
    dev.save(update_fields=['image'])
    count+=1
print('v4',count)
